{
  "name": "Préstamos de portátiles y material · práctica",
  "active": false,
  "nodes": [
    {
      "id": "prestamo-material-0",
      "name": "Empezar práctica",
      "type": "n8n-nodes-base.manualTrigger",
      "typeVersion": 1,
      "position": [
        0,
        0
      ],
      "parameters": {}
    },
    {
      "id": "prestamo-material-1",
      "name": "Datos de ejemplo",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        240,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "return [{ json: {\"id\":\"MAT-01\",\"item\":\"Laptop\",\"requested\":3,\"available\":2} }];"
      }
    },
    {
      "id": "prestamo-material-2",
      "name": "Comprobar el número",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        480,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "const seen = new Set(); return $input.all().map(item => { const x = item.json; if (typeof x.id !== 'string' || !x.id.trim()) throw new Error('Missing id'); const sample = {\"id\":\"MAT-01\",\"item\":\"Laptop\",\"requested\":3,\"available\":2}; for (const [key,value] of Object.entries(sample)) { if (!(key in x)) throw new Error('Missing field: '+key); if (value !== null && typeof x[key] !== typeof value) throw new Error('Wrong type: '+key); if (typeof value === 'number' && (!Number.isFinite(x[key]) || x[key] < 0)) throw new Error('Invalid number: '+key); } if (seen.has(x.id)) throw new Error('Repeated id in this run'); seen.add(x.id); return item; });"
      }
    },
    {
      "id": "prestamo-material-3",
      "name": "Préstamos de portátiles y material",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        720,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "return $input.all().map(item => { const x = item.json; return { json: { ...x, result: x.requested > x.available ? \"review\" : \"ready\" } }; });"
      }
    },
    {
      "id": "prestamo-material-4",
      "name": "Dejar para revisión",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        960,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "return $input.all().map(item => ({ json: { ...item.json, reviewedBy: '', approved: false } }));"
      }
    },
    {
      "id": "prestamo-material-5",
      "name": "Mostrar el resultado",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        1200,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "return $input.all().map(item => ({ json: { ...item.json, practiceOnly: true, savedExternally: false } }));"
      }
    }
  ],
  "connections": {
    "Empezar práctica": {
      "main": [
        [
          {
            "node": "Datos de ejemplo",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Datos de ejemplo": {
      "main": [
        [
          {
            "node": "Comprobar el número",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Comprobar el número": {
      "main": [
        [
          {
            "node": "Préstamos de portátiles y material",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Préstamos de portátiles y material": {
      "main": [
        [
          {
            "node": "Dejar para revisión",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Dejar para revisión": {
      "main": [
        [
          {
            "node": "Mostrar el resultado",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "settings": {
    "executionOrder": "v1"
  }
}

